const isPrivate = ip => /^(10\.|127\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(ip);
const out = [];

for (const item of $input.all()) {
  const r = item.json;
  const src = String(r['Source'] ?? '').trim();
  const dst = String(r['Destination'] ?? '').trim();
  const time = String(r['Date/Time'] ?? '').trim();
  if (!src || !time) continue;                 // skip blank rows

  // Source/Destination are swapped in this export, so use whichever IP is public as the client
  const client_ip = !isPrivate(src) ? src : (!isPrivate(dst) ? dst : src);
  const server_ip = client_ip === src ? dst : src;

  out.push({ json: {
    id: r['#'],
    time,
    ts: Date.parse(time.replace(' ', 'T')),
    action: r['Action'],
    policy: r['Policy'],
    client_ip,
    server_ip,
    host: r['HTTP Host'],
    url: r['URL'],
    main_type: r['Main Type'],
    sub_type: r['Sub Type'],
    threat_level: r['Threat Level'],
  }});
}
return out;

const WINDOW_MS = 10 * 60 * 1000;
const ALLOWLIST = [];   // e.g. ['203.0.113.10'] your own scanners / monitoring IPs

const events = $input.all().map(i => i.json).sort((a, b) => a.ts - b.ts);

const byIp = {};
for (const e of events) (byIp[e.client_ip] ||= []).push(e);

const groups = [];
for (const [ip, list] of Object.entries(byIp)) {
  let g = null;
  for (const e of list) {
    if (!g || e.ts - g.last_ts > WINDOW_MS) {
      g = { client_ip: ip, count: 0, types: {}, main_types: new Set(), policies: new Set(),
            hosts: new Set(), actions: new Set(), first_time: e.time, last_time: e.time,
            first_ts: e.ts, last_ts: e.ts };
      groups.push(g);
    }
    g.count++;
    g.last_ts = e.ts;
    g.last_time = e.time;
    g.types[e.sub_type] = (g.types[e.sub_type] || 0) + 1;
    g.main_types.add(e.main_type);
    g.policies.add(e.policy);
    g.hosts.add(e.host);
    g.actions.add(e.action);
  }
}

// Several IPs from the same /24 = likely one scanner or botnet
const subnetIps = {};
for (const g of groups) {
  g.subnet = g.client_ip.split('.').slice(0, 3).join('.');
  (subnetIps[g.subnet] ||= new Set()).add(g.client_ip);
}

return groups.map(g => ({ json: {
  client_ip: g.client_ip,
  count: g.count,
  types: g.types,
  distinct_types: Object.keys(g.types).length,
  main_types: [...g.main_types],
  policies: [...g.policies],
  hosts: [...g.hosts],
  actions: [...g.actions],
  first_time: g.first_time,
  last_time: g.last_time,
  duration_sec: Math.round((g.last_ts - g.first_ts) / 1000),
  subnet: g.subnet + '.0/24',
  subnet_peers: subnetIps[g.subnet].size,
  allowlisted: ALLOWLIST.includes(g.client_ip),
}}));

const { data, ...a } = $input.item.json;
const abuse = data?.abuseConfidenceScore ?? 0;

const TYPE_POINTS = {
  'Generic Attacks(Extended)': 35,
  'Information Disclosure': 30,
  'Illegal HTTP Version': 20,
  'Header Value Length Violation': 15,
  'HTTP Parsing Error': 10,
  'HTTP Duplicated Parameter Name': 10,
  'Missing POST Content Type': 5,
  'N/A': 10,
};
const HIGH_RISK = /sql|xss|injection|traversal|command|rce|shell/i;

let score = 0;
const reasons = [];

let top = 0, topName = '';
for (const t of Object.keys(a.types)) {
  const p = HIGH_RISK.test(t) ? 50 : (TYPE_POINTS[t] ?? 15);
  if (p > top) { top = p; topName = t; }
}
score += top; reasons.push(`worst type: ${topName} (+${top})`);

if (a.distinct_types > 1) {
  const p = (a.distinct_types - 1) * 5;
  score += p; reasons.push(`${a.distinct_types} different types (+${p})`);
}

const vol = a.count >= 50 ? 25 : a.count >= 10 ? 15 : a.count >= 5 ? 10 : 0;
if (vol) { score += vol; reasons.push(`${a.count} events (+${vol})`); }

if (a.subnet_peers >= 3) { score += 15; reasons.push(`${a.subnet_peers} IPs from ${a.subnet} (+15)`); }

if (abuse >= 80) { score += 40; reasons.push(`AbuseIPDB ${abuse}% (+40)`); }
else if (abuse >= 40) { score += 20; reasons.push(`AbuseIPDB ${abuse}% (+20)`); }

const prod = a.policies.some(p => /prod/i.test(p));
if (prod) { score += 5; reasons.push('production policy (+5)'); }

score = Math.min(score, 100);
const level = score >= 70 ? 'high' : score >= 45 ? 'medium' : score >= 25 ? 'low' : 'ignore';

const llm_payload = {
  source_ip: a.client_ip,
  country: data?.countryCode ?? 'unknown',
  isp: data?.isp ?? 'unknown',
  abuseipdb_score: abuse,
  abuseipdb_total_reports: data?.totalReports ?? 0,
  events: a.count,
  window: `${a.first_time} to ${a.last_time}`,
  attack_types: a.types,
  waf_actions: a.actions,
  environment: prod ? 'production' : 'non-production',
  other_ips_in_same_subnet: a.subnet_peers - 1,
  score,
  rule_reasons: reasons,
};

return { json: {
  ...a,
  country: data?.countryCode, isp: data?.isp, abuse_score: abuse,
  score, level, reasons, llm_payload,
}};

